import Mathlib

theorem countable_rectangle_outer_measure_eq
    (n : ℕ) (hn : 0 < n) (S : Set (Fin n → ℝ)) :
    let Rectangle := (Fin n → ℝ) × (Fin n → ℝ)
    let rect : Rectangle → Set (Fin n → ℝ) :=
      fun r => {x | ∀ i, r.1 i < x i ∧ x i < r.2 i}
    let volume : Rectangle → ENNReal :=
      fun r => ∏ i, ENNReal.ofReal (r.2 i - r.1 i)
    let mStar : Set (Fin n → ℝ) → ENNReal :=
      fun A => sInf {c | ∃ R : ℕ → Rectangle,
        (∀ j i, (R j).1 i < (R j).2 i) ∧
        A ⊆ (⋃ j, rect (R j)) ∧
        c = ∑' j, volume (R j)}
    let muStar : Set (Fin n → ℝ) → ENNReal :=
      fun A => sInf {c | ∃ (I : Set ℕ) (R : ℕ → Rectangle),
        (∀ j ∈ I, ∀ i, (R j).1 i < (R j).2 i) ∧
        A ⊆ (⋃ j ∈ I, rect (R j)) ∧
        c = ∑' j : I, volume (R j)}
    muStar S = mStar S := by sorry

